insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('sam-cobix-3310-review-and-ping-2026-11-14','decision','Sam: review COBIx''s #3310 comments, decide and tell him','Sam, in session S653, about 17:23Z 2026-11-14: "comix has some comments for you in 3310. ping him when you''ve reviewed them and let him know how you decide to move forward" (COBIx, issue #3310, College Data Collection). The conductor reviewed them, decided (d-cdc-four-prs-and-classes-s653) and answered on #3310.',array['commons','college-data-collection','decision'],'verified','Sam, in session S653 (verbatim)','Sam Lee',now(),'SkyGodwit (S653)',date '2026-11-14'),
('d-crsid-seven-retire-ten-stay-s653','decision','The course-id route retires 7 of slice C''s 17 prefix-alias pairs','The S653 conductor, #3312 (b00fca4f): the prefix comes from the Program Course File course id first. 7 pairs retire (American River BMET, SWCD; Barstow CDEV; CCSF COMM; Diablo Valley BIOL; Riverside City HIST; Santiago Canyon PASV), 10 stay; Crafton Hills, Moreno Valley and Norco keep theirs (COCI carries HIS, never HIST). On filed records 8 fail to pass, 0 pass to fail.',array['program-requirements-harvest','reconcile','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-rescore-five-after-crsid-merge-s653','decision','Rescore the five rereads once on the course-id route''s code','The S653 conductor: the five rereads (Merced, Moreno Valley, Norco, San Bernardino Valley, Diablo Valley; #3317 to #3321) ran on main''s code before #3312 merged. After COBIx''s spot-check (#3299, comment 6881825340) and one display rebuild, one rescore on the course-id route''s code, so every filed score comes from one code version (66 scores change, one status: Diablo Valley 37558).',array['program-requirements-harvest','reconcile','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-ge-page-one-owner-s653','decision','A GE-pattern page has one owner; ties refuse','The S653 conductor, #3324 (ge_page_owner): a GE-pattern page has one owner, settled by title words both ways, award, version and a printed control number; a tie refuses. 88 filed claims allowed, 52 refused; 82 claims move at six colleges (Riverside City 36, Moreno Valley 27, LA Trade-Tech 7, Norco 6, Pierce 4, LA Valley 2). It fixes the S646 claim rule that skipped transfer degrees'' own pages.',array['program-requirements-harvest','capture','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-extraction-gate-every-run-s653','decision','The $40 estimate gate and hard stop run on every paid extraction','The S653 conductor, #3327 and #3330: the $40 estimate gate and hard stop run on every paid extraction, fresh or restaged (college workflow, extract and second-reader workflows). Three model callers stay ungated until Sam gives a figure: cer-classify (cer-procedures.yml), cpl-news-harvest (cpl-news.yml), cpl-chat (sierra-ask.yml, cpl-chat-preview-ab.yml, about 66 billed answers a run).',array['program-requirements-harvest','governance-team-enablement','cost','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-skyline-estimate-5-20-s653','decision','Skyline''s found programs: about $5.20, extracted only after slice B','The S653 conductor: Skyline has 52 found of 86 no-closed-list programs; the estimate is about $5.20 (52 x $0.08 floor x 1.25). Nothing extracts a found program until slice B. The 23 empty-heading pages get a spot-check first; COBIx is asked (#3299, comment 6881980522) whether an empty h1 is not_matched or stays found with named courses required (the conductor leans to the second).',array['program-requirements-harvest','catalog-first','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-honors-open-questions-s653','decision','Honors: the open questions settled before the rows','The S653 conductor, for the honors_of rows: rows on C-ID bases, yes; multi-base pairs wait; one H id per base; the three promotions.json pairs held, then released; HIST M10UP folds into HIST C1001H as its own change; #3304''s dismissal rows stay; a pair beside a CCN H record is held.',array['commons','honors','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-honors-two-signals-or-hold-s653','decision','Honors step 2 writes a row only where two derivations agree','The S653 conductor, #3315: step 2 writes an honors_of row only for a pair two independent derivations find; a base holding more than one course is held until split; --check recomputes the plan on the day. Redrawn twice: 553 pairs (267 row and mint, 78 row only, 4 fold, 88 none, 116 held), 347 rows to write under honors-rows-s653@bot.',array['commons','honors','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-cdc-four-prs-and-classes-s653','decision','College Data Collection: #3310 in four PRs, and its data classes','The S653 conductor on COBIx''s #3310: four PRs (#3314 sort and panel, merged; #3316 three college cards; #3323 the data dictionary; #3326 the integrations view). Classes: staff role contacts held and left out of any outside share; MAP articulation Status held; MAP student counts aggregate under the student-detail ADR; one definitions file and one integrations registry.',array['commons','college-data-collection','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-scouting-cadence-s653','decision','Stack scouting: every other Monday, one line per trial','The S653 conductor, on Sam''s S652 ask that COBIx scout repos for the stack: COBIx scans every other Monday and off-cycle on a measured cost; #3306 is the thread; docs/reference/stack_scouting.md gets one line per trial (candidate, measured cost, result, kept or dropped). First rows, not started: Serena on the reader file, a session cost report, pdfplumber, pgTAP.',array['governance-team-enablement','conductor','scouting','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('d-two-sessions-one-writer-s653','decision','Two sessions from one opening line split the work by message','The S653 conductor and a second session opened 18:33Z from the same opening line (session_01Rvwe2XkSiUQhXResuxH8tP) agreed by message at 18:38Z: the second takes the two failing Python tests, the library, governance and workplan lane items (one writer of those lane files), the four S652 wiki pages, Allan Hancock #3284 and sac, and #3315''s third review. This one kept the rest.',array['governance-team-enablement','conductor','decision'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('cq-distinct-not-the-riverside-fault-s653','fact','cq_distinct was not Riverside City''s fault; the S646 claim rule was','S653: a capture on instrumented code (#3311, 8b6caff8, curriQunet twin ids recorded) cleared cq_distinct as the cause of Riverside City''s missing pages. The fault was the S646 rule at candidates(), which skipped each transfer degree''s own GE-pattern page; #3324 fixes it. The S652 lane line naming cq_distinct is superseded.',array['program-requirements-harvest','capture','fact'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('skyline-ncl-first-merged-capture-s653','fact','Skyline, the first capture on merged slice A: 52 found, 34 not_matched','S653, free capture 43619276697 on merged slice A (#3300): Skyline''s 86 no-closed-list programs read 52 found and 34 not_matched. Two records on main are filed on the wrong page: 46296 on dance-aa.php and 32337 on the Advanced Engine page. 23 found pages have an empty h1.',array['program-requirements-harvest','catalog-first','fact'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('ppm-list-60-not-63-s653','fact','The Pathways Mapper member list holds 60, not the 63 pasted','S653, #3316: the Program Pathways Mapper member list holds 60 rows; the S444 header says the pasted list named 63. Which three were never filed is not recorded; Sam or the MAP team can say. Of 118 colleges, program maps: 65 held, 48 none found when looked for, 5 not known.',array['commons','college-data-collection','fact'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('merced-summary-stale-s653','fact','Merced''s passing summary of 134 was an old extraction''s','S653: Merced''s summary showed 134 passing, an old extraction''s count. The live count before the S653 reread was 141 of 163, and 144 after it (reread run 43619524339, 28 rows replaced; newly passing 19370, 33625, 41857).',array['program-requirements-harvest','status','fact'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('p-disk-three-checkouts-s653','pitfall','Four worker checkouts filled the disk twice; three is the ceiling','S653: four worker checkouts (4.7 GB each) filled the disk twice within ten minutes, and a worker pushed through the GitHub API with check_generated.sh unrun. Three checkouts at once is the ceiling; a read-only task takes no worktree; never write a tar.',array['conductor','disk','pitfall'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('p-diagnosis-flipped-three-times-s653','pitfall','A diagnosis flipped three times before the code was instrumented','S652 blamed cq_distinct for Riverside City''s missing pages; S653 cleared it, blamed it again from one capture''s counts, then cleared it with a capture on instrumented code (#3311). The fault was the S646 claim rule (#3324). Instrument the code and run it before fixing.',array['program-requirements-harvest','conductor','pitfall'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('p-reviewers-missed-the-capture-path-s653','pitfall','Five readers checked the scorer; none ran the page finder','S653, #3312: five readers checked scoring and none ran the page finder; COBIx found the capture-path gap. Name each code path in the review brief. A restaged run loads no page, so it proves the scorer only.',array['program-requirements-harvest','conductor','review','pitfall'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('p-snapshot-test-pins-the-rule-s653','pitfall','A test took its rule''s own output as the truth','S653: #3324''s GE_ALLOWED pinned the claim rule''s own output, and #3315''s recall script counted the matcher''s pairs minus a wrong list as right, sharing the matcher''s parser. Expected answers are written by hand or by an independent derivation. Note: docs/kb-notes/methodology-a-test-must-not-take-its-rule-as-the-truth.md.',array['program-requirements-harvest','commons','testing','pitfall'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('p-sources-from-wants-the-capture-run-s653','pitfall','sources_from takes the capture run, not the reconcile run','S653: a reread was given the day''s reconcile run as sources_from; it takes the run that captured the pages (Moreno Valley 38111056537). The guard refused it.',array['program-requirements-harvest','reconcile','pitfall'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('p-subscription-notices-cost-context-s653','pitfall','PR subscription notices cost about 8,000 tokens each','S653: each PR subscription notice cost about 8,000 tokens, and workers'' PRs subscribed the session; context went 16% to 73% in 100 minutes. Unsubscribe from a worker''s PR at once and gate it at a scheduled check-in.',array['conductor','context','pitfall'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('p-at-mention-in-worker-comment-s653','pitfall','A worker''s comment @-mentioned COBIx by name, not login','S653: a worker''s PR comment opened "@COBIx", which is not his login (cobi-cto); it was edited out. A bare @name notifies whoever holds that login; write COBIx''s name without the @.',array['conductor','github','pitfall'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14'),
('p-worker-not-resumable-after-worktree-removed-s653','pitfall','A worker cannot resume once its checkout is removed','S653: a worker could not be resumed after its worktree was removed. Remove a checkout only when its worker is finished for good.',array['conductor','worktree','pitfall'],'proposed','S653 checkpoint; docs/session_654_handoff.md and the lane files',null,null,'SkyGodwit (S653)',date '2026-11-14')
